#[cfg(windows)] {
    use std::os::windows::ffi::OsStringExt;
    let units = path.code_units();
    let split = units.iter().rposition(|u| *u == 47 || *u == 92).map_or(0, |i| i + 1);
    let mut wrong = units[..split].to_vec();
    wrong.extend(String::from_utf16_lossy(&units[split..]).encode_utf16());
    PathBuf::from(std::ffi::OsString::from_wide(&wrong))
}
#[cfg(not(windows))] { PathBuf::from(String::from_utf16_lossy(path.code_units())) }
